internal static class LightPrintAudit
{
 public static void Run(string manifest,string output)
 {
  output=Path.GetFullPath(output);if(Directory.Exists(output))throw new IOException("Fresh audit required");Directory.CreateDirectory(output);Exception? error=null;
  var thread=new Thread(()=>{var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var doc=XDocument.Load(Path.Combine(Directory.GetCurrentDirectory(),"src/RAWSelectionAssistant/App.xaml"));foreach(var a in doc.Descendants().Attributes("Source"))app.Resources.MergedDictionaries.Add((ResourceDictionary)Application.LoadComponent(new Uri("/KitaoPhotoSelector;component/"+a.Value,UriKind.Relative)));app.Dispatcher.InvokeAsync(async()=>{try{await Execute(manifest,output);}catch(Exception e){error=e;}finally{app.Shutdown();}});app.Run();});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(error is not null)throw new InvalidOperationException("Lightprint audit failed",error);
 }
 static string Hash(string path){using var f=File.OpenRead(path);return Convert.ToHexString(SHA256.HashData(f));}
 static string Pixels(BitmapSource b){var c=new FormatConvertedBitmap(b,PixelFormats.Rgb48,null,0);var a=new byte[c.PixelWidth*c.PixelHeight*6];c.CopyPixels(a,c.PixelWidth*6,0);return Convert.ToHexString(SHA256.HashData(a));}
 static void Require(bool x,string why){if(!x)throw new InvalidDataException(why);}
 static void Screen(FrameworkElement page,string path,int w,int h){page.Measure(new Size(w,h));page.Arrange(new Rect(0,0,w,h));page.UpdateLayout();var b=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);b.Render(page);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(path);enc.Save(f);}
 static async Task Execute(string manifest,string output)
 {
  var entries=JsonSerializer.Deserialize<InstantReviewInput[]>(File.ReadAllText(manifest))!;var files=new List<string>();
  foreach(var e in entries.Take(2)){Require(Hash(e.FrozenTiff)==e.ExpectedFrozenSha256,"Frozen source identity");var path=Path.Combine(output,e.Id+".png");StudioQuickExport.Encode(StudioQuickExport.Load(e.FrozenTiff,1000),e.FrozenTiff,path,StudioExportFormat.Png);files.Add(path);}
  var screenshot=Path.Combine(output,"screenshots");Directory.CreateDirectory(screenshot);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(output));await vm.LoadTargetAsync(files[0]);await vm.LoadTargetAsync(files[1]);await vm.ActivateTargetCommand.ExecuteAsync(vm.Targets[0]);vm.UsePhotoGradePage=true;
  var page=new PhotoGradePageView{DataContext=vm};var tabs=(TabControl)page.FindName("EditModes");tabs.SelectedIndex=1;Screen(page,Path.Combine(screenshot,"01-darkroom-1366.png"),1366,768);Screen(page,Path.Combine(screenshot,"01-darkroom-1920.png"),1920,1080);
  var baseline=Pixels(vm.Editor.MatchedImage??vm.Editor.SourceImage!);var target=vm.ActiveTarget!;var count=target.EditVersions.Count;vm.SelectedPhotographerPaperId="blue-duochrome600";await vm.LightPrintPreviewWork;var paper=Pixels(vm.Editor.MatchedImage!);Require(paper!=baseline,"Selecting paper changes central image without develop");Require(target.RawDefinition is null&&target.EditVersions.Count==count,"Preview not persisted as developed");
  vm.SelectedLightPrintFrameId="generic.white.circle";await vm.LightPrintPreviewWork;var frame=Pixels(vm.Editor.MatchedImage!);Require(frame!=paper,"Frame changes preview");Screen(page,Path.Combine(screenshot,"02-preview-circle-1366.png"),1366,768);Screen(page,Path.Combine(screenshot,"02-preview-circle-1920.png"),1920,1080);
  vm.SelectedPhotographerPaperId="itype-bw";vm.SelectedPhotographerPaperId="sx70-color";vm.SelectedPhotographerPaperId="itype-color";await vm.LightPrintPreviewWork;Require(vm.SelectedPhotographerPaperId=="itype-color","Last click wins");vm.InstantCameraAnimation=false;await vm.DevelopLightPrintCommand.ExecuteAsync(null);Require(vm.IsLightPrintLocked,"Develop locks recipe");var variant=target.ActiveEditVersionId;var frozen=JsonSerializer.Serialize(target.RawDefinition);var original=target.RawDefinition!;using var before=ProfessionalRawPipeline.RenderPreview(target.LinearRawMaster!,original,1600);
  tabs.SelectedIndex=0;vm.Editor.AddAdjustmentNodeCommand.Execute("BasicTone");vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure"),.65);await vm.ApplyWindowGradeCommand.ExecuteAsync(null);Require(target.ActiveEditVersionId==variant,"Window grade same variant");using var after=ProfessionalRawPipeline.RenderPreview(target.LinearRawMaster!,target.RawDefinition!,1600);Require(before.Rgb32.Span[0]==after.Rgb32.Span[0]&&before.Rgb32.Span[^1]==after.Rgb32.Span[^1],"Border unchanged");
  Screen(page,Path.Combine(screenshot,"03-window-grade-1366.png"),1366,768);Screen(page,Path.Combine(screenshot,"03-window-grade-1920.png"),1920,1080);await vm.PhotoGradeUndoCommand.ExecuteAsync(null);await vm.PhotoGradeRedoCommand.ExecuteAsync(null);
  var graded=JsonSerializer.Serialize(target.RawDefinition);vm.ReshootLightPrintCommand.Execute(null);vm.SelectedPhotographerPaperId="itype-bw";await vm.LightPrintPreviewWork;await vm.DevelopLightPrintCommand.ExecuteAsync(null);Require(target.ActiveEditVersionId!=variant,"Reshoot creates variant");var newer=target.ActiveEditVersionId;await vm.SwitchEditVersionAsync(variant!.Value);Require(JsonSerializer.Serialize(target.RawDefinition)==graded,"Old variant preserved");tabs.SelectedIndex=4;Screen(page,Path.Combine(screenshot,"04-variants-1366.png"),1366,768);Screen(page,Path.Combine(screenshot,"04-variants-1920.png"),1920,1080);
  await vm.LoadTargetAsync(files[1]);await vm.ActivateTargetCommand.ExecuteAsync(target);var project=Path.Combine(output,"darkroom.ptstudio.json");await vm.SaveSessionAsync(project);using var reopened=new ReferenceColorWorkspaceViewModel(new Dialogs(output));await reopened.LoadSessionAsync(project);Require(JsonSerializer.Serialize(reopened.ActiveTarget!.RawDefinition)==graded,"Reopen exact definition");var exports=new List<object>();
  foreach(var format in new[]{StudioExportFormat.Png,StudioExportFormat.Tiff,StudioExportFormat.Jpeg}){var folder=Path.Combine(output,"export",format.ToString());Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("PIXEL_TART_ACCEPTANCE_EXPORT_DIRECTORY",folder);foreach(var t in reopened.Targets)t.IsSelected=ReferenceEquals(t,reopened.ActiveTarget);reopened.QuickExportFormat=format;await reopened.ExportSelectedCommand.ExecuteAsync(null);Require(reopened.ActiveTarget.ExportStatus==ReferenceExportStatus.Succeeded,reopened.ActiveTarget.Error??reopened.StatusText);exports.Add(new{format,path=reopened.ActiveTarget.OutputPath,sha256=Hash(reopened.ActiveTarget.OutputPath!),inspection=reopened.ActiveTarget.LastProfessionalOutput});}
  Environment.SetEnvironmentVariable("PIXEL_TART_ACCEPTANCE_EXPORT_DIRECTORY",null);File.WriteAllText(Path.Combine(output,"RESULT.json"),JsonSerializer.Serialize(new{paperChangesImmediately=true,frameChangesImmediately=true,latestClickWins=true,developedVariant=variant,reshootVariant=newer,recipeLocked=true,borderUnaffected=true,saveReopen=true,exports,frameIds=LightPrintFrames.Available.Select(f=>f.Id),physicalMouse="NOT_RUN: Computer Use native pipe unavailable",screenMethod="Real WPF offscreen RenderTargetBitmap, 1366x768 and1920x1080; no physical mouse claim",definition=reopened.ActiveTarget.RawDefinition},new JsonSerializerOptions{WriteIndented=true}));
 }
